import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";
import type { ElementProps } from "@/lib/types";

export const textVariants = cva("", {
  variants: {
    variant: {
      body: "text-ds-text ds-type-body",
      lead: "text-ds-text ds-type-lead",
      caption: "text-ds-text-muted ds-type-caption",
      label: "text-ds-text ds-type-label",
    },
  },
  defaultVariants: { variant: "body" },
});

export type TextElement = "p" | "span" | "div" | "label";

type TextStyleProps = VariantProps<typeof textVariants>;

/**
 * Element-specific props and ref type per `as`. `htmlFor` only exists on
 * `as="label"`; `ref` is typed to the chosen element.
 */
export type TextProps = TextStyleProps &
  (
    | ({ as?: "p" } & ElementProps<"p">)
    | ({ as: "span" } & ElementProps<"span">)
    | ({ as: "div" } & ElementProps<"div">)
    | ({ as: "label" } & ElementProps<"label">)
  );

export const Text = ({ as = "p", variant, className, ...props }: TextProps) => {
  // Widened internally for the dynamic tag; the public `TextProps` union
  // enforces the per-element props and ref type at the call site.
  const Comp: React.ElementType = as;
  return (
    <Comp
      {...(props as object)}
      data-slot="text"
      className={cn(textVariants({ variant }), className)}
    />
  );
};

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";
import type { ElementProps } from "@/lib/types";

export const headingVariants = cva("text-ds-text", {
  variants: {
    variant: {
      display: "ds-type-display",
      h1: "ds-type-h1",
      h2: "ds-type-h2",
      h3: "ds-type-h3",
    },
  },
  defaultVariants: { variant: "h1" },
});

export type HeadingVariant = NonNullable<
  VariantProps<typeof headingVariants>["variant"]
>;
export type HeadingElement = "h1" | "h2" | "h3" | "h4" | "h5" | "h6";

/** Default element per variant. Static map, never built from strings. */
export const headingDefaultElement: Record<HeadingVariant, HeadingElement> = {
  display: "h1",
  h1: "h1",
  h2: "h2",
  h3: "h3",
};

export type HeadingProps = Omit<ElementProps<"h1">, "as" | "variant"> &
  VariantProps<typeof headingVariants> & {
    /** HTML heading level. Independent of `variant`; derived from it if omitted. */
    as?: HeadingElement;
  };

export const Heading = ({ as, variant, className, ...props }: HeadingProps) => {
  const resolved: HeadingVariant = variant ?? "h1";
  const Comp = as ?? headingDefaultElement[resolved];
  return (
    <Comp
      {...props}
      data-slot="heading"
      className={cn(headingVariants({ variant: resolved }), className)}
    />
  );
};
